func main() {
	// pod memory limit is 2 GiB — match it exactly
	debug.SetMemoryLimit(2 << 30)
	// disable GOGC: the memory limit alone will trigger collection
	debug.SetGCPercent(-1)

	go func() {
		for range time.Tick(time.Minute) {
			var m runtime.MemStats
			runtime.ReadMemStats(&m)
			log.Printf("heap_mb=%d num_gc=%d", m.HeapAlloc>>20, m.NumGC)
		}
	}()

	if err := run(); err != nil {
		log.Fatal(err)
	}
}
